// Per-install API token. Generated by the server on first run and served from
// /token; cached in chrome.storage. Fetching it is ASYNC, so every authed call
// goes through kamFetch(), which waits for the token before sending. Otherwise a
// click made before the token arrives sends an empty header and gets a 403.
let KAM_TOKEN = "";
let _tokenPromise = null;
function _ensureToken() {
  if (KAM_TOKEN) return Promise.resolve(KAM_TOKEN);
  if (_tokenPromise) return _tokenPromise;          // one in-flight fetch, shared
  // The slot is cleared in a finally, since the early return on a stored token
  // used to skip the clear. The settled promise then stayed in the slot, so
  // after a stale token was dropped this kept handing the same one back.
  _tokenPromise = (async () => {
    try {
      try {
        const st = await chrome.storage.local.get("kamToken");
        if (st.kamToken) { KAM_TOKEN = st.kamToken; return KAM_TOKEN; }
      } catch (e) {}
      try {
        const r = await fetch("http://127.0.0.1:5050/token");
        if (r.ok) {
          KAM_TOKEN = (await r.json()).token || "";
          if (KAM_TOKEN) chrome.storage.local.set({ kamToken: KAM_TOKEN });
        }
      } catch (e) { /* server down, so it is retried on the next call */ }
      return KAM_TOKEN;
    } finally {
      _tokenPromise = null;                          // allow a later retry
    }
  })();
  return _tokenPromise;
}

// Drop-in replacement for fetch() on authed server endpoints: waits for the
// token, then injects the header. Returns the same promise shape as fetch.
//
// A 403 means the cached token is stale, since the server makes a new one when
// kam_token.txt is missing or cannot be written. The cache used to be kept for
// good, so every call was refused from then on. So I drop it, in memory and in
// storage, ask for the token again and retry once, but only with a token that
// actually differs, because the same one would just be refused again.
async function kamFetch(url, opts = {}) {
  const send = tok => fetch(url, Object.assign({}, opts, {
    headers: Object.assign({}, opts.headers || {}, { "X-KAM-Token": tok })
  }));
  const tok = await _ensureToken();
  const res = await send(tok);
  if (res.status !== 403) return res;
  KAM_TOKEN = "";
  try { await chrome.storage.local.remove("kamToken"); } catch (e) {}
  const fresh = await _ensureToken();
  if (!fresh || fresh === tok) return res;
  return send(fresh);
}
_ensureToken();   // warm the cache as soon as the popup opens

const SERVER = "http://127.0.0.1:5050";
let currentMode       = "selection";
let allChunks         = [];
let currentChunkIndex = 0;


// Strip semantic markers from chunk text before displaying in the UI.
// The markers are only for the TTS server, so what you see stays clean.
// --- Theme & reading overlay settings ---
// Three themes live in popup.html as [data-theme="..."] palettes; here we
// persist the user's choice and reapply it on every popup open. Overlay
// settings (line colour + text size) live in chrome.storage.local so the
// content-script overlay can read them without round-tripping through the
// background worker.
const POPUP_SETTINGS_DEFAULTS = {
  popupTheme:        "arian",
  overlayLineColour: "#f5c518",   // effective highlight colour (derived)
  overlayBarColour:  "#0f0f0f",   // effective bar background colour (derived)
  overlayTextSize:   12,
  // Per-theme custom colours. Every theme is now customisable; these seed the
  // pickers and are what the effective colours are derived from. Defaults are
  // the tuned presets for each theme.
  themeColours: {
    arian: { highlight: "#f5c518", bar: "#0f0f0f" },
    light: { highlight: "#0078d4", bar: "#ffffff" },
    dark:  { highlight: "#4cc2ff", bar: "#1b1a19" },
  },
};

// Factory defaults per theme, used by the "reset this theme" button.
const THEME_COLOUR_DEFAULTS = {
  arian: { highlight: "#f5c518", bar: "#0f0f0f" },
  light: { highlight: "#0078d4", bar: "#ffffff" },
  dark:  { highlight: "#4cc2ff", bar: "#1b1a19" },
};

function applyPopupTheme(name) {
  const valid = ["arian", "light", "dark"];
  if (!valid.includes(name)) name = "arian";
  document.body.setAttribute("data-theme", name);
  document.querySelectorAll(".theme-btn").forEach(b => {
    b.classList.toggle("active", b.dataset.theme === name);
  });
}

function initSettings() {
  let _activeTheme = "arian";
  let _themeColours = JSON.parse(JSON.stringify(POPUP_SETTINGS_DEFAULTS.themeColours));

  const hlPicker  = document.getElementById("ov-hl-colour");
  const hlVal     = document.getElementById("ov-hl-colour-val");
  const barPicker = document.getElementById("ov-bar-colour");
  const barVal    = document.getElementById("ov-bar-colour-val");
  const themeName = document.getElementById("cust-theme-name");

  // Paint the pickers + effective colours for the active theme, and persist the
  // effective colours so content.js (overlay + highlight) updates live.
  function reflectTheme(theme) {
    // Guard every layer: an old or partial stored themeColours, or an unknown
    // theme name, must never crash the popup. Fall back to defaults, then to a
    // safe literal.
    theme = theme || "arian";
    _activeTheme = theme;
    const c = (_themeColours && _themeColours[theme])
              || THEME_COLOUR_DEFAULTS[theme]
              || THEME_COLOUR_DEFAULTS.arian
              || { highlight: "#f5c518", bar: "#0f0f0f" };
    if (hlPicker)  hlPicker.value  = c.highlight;
    if (hlVal)     hlVal.textContent = c.highlight;
    if (barPicker) barPicker.value = c.bar;
    if (barVal)    barVal.textContent = c.bar;
    if (themeName) themeName.textContent =
      theme.charAt(0).toUpperCase() + theme.slice(1) + " · highlight colour";
    chrome.storage.local.set({
      overlayLineColour: c.highlight,
      overlayBarColour:  c.bar,
    });
  }

  chrome.storage.local.get(POPUP_SETTINGS_DEFAULTS, (cfg) => {
    // Merge stored colours OVER the full defaults, so a partial/old stored
    // object (missing a theme) still yields a complete map.
    _themeColours = Object.assign(
      {}, JSON.parse(JSON.stringify(THEME_COLOUR_DEFAULTS)), cfg.themeColours || {}
    );
    // Ensure each theme entry is itself complete.
    for (const t of Object.keys(THEME_COLOUR_DEFAULTS)) {
      _themeColours[t] = Object.assign({}, THEME_COLOUR_DEFAULTS[t], _themeColours[t] || {});
    }
    applyPopupTheme(cfg.popupTheme);
    reflectTheme(cfg.popupTheme);

    const ovSize    = document.getElementById("ov-size");
    const ovSizeVal = document.getElementById("ov-size-val");
    if (ovSize)    ovSize.value = cfg.overlayTextSize;
    if (ovSizeVal) ovSizeVal.textContent = cfg.overlayTextSize + "px";
  });

  // Theme buttons, which switch the theme and load that theme's saved colours
  // into the pickers.
  document.querySelectorAll(".theme-btn").forEach(btn => {
    btn.addEventListener("click", () => {
      const theme = btn.dataset.theme;
      applyPopupTheme(theme);
      chrome.storage.local.set({ popupTheme: theme });
      reflectTheme(theme);
    });
  });

  // Collapsible panel.
  const toggle = document.getElementById("settings-toggle");
  const panel  = document.getElementById("settings-panel");
  if (toggle && panel) {
    chrome.storage.local.get({ settingsOpen: false }, d => {
      panel.style.display = d.settingsOpen ? "block" : "none";
    });
    toggle.addEventListener("click", () => {
      const open = panel.style.display !== "block";
      panel.style.display = open ? "block" : "none";
      chrome.storage.local.set({ settingsOpen: open });
    });
  }

  // Persist a colour edit into the ACTIVE theme's profile + push effective.
  function saveColour(kind, value) {
    if (!_themeColours[_activeTheme]) _themeColours[_activeTheme] = {};
    _themeColours[_activeTheme][kind] = value;
    const eff = _themeColours[_activeTheme];
    chrome.storage.local.set({
      themeColours: _themeColours,
      overlayLineColour: eff.highlight,
      overlayBarColour:  eff.bar,
    });
  }

  if (hlPicker) {
    hlPicker.addEventListener("input", () => {
      hlVal.textContent = hlPicker.value;
      saveColour("highlight", hlPicker.value);
    });
  }
  if (barPicker) {
    barPicker.addEventListener("input", () => {
      barVal.textContent = barPicker.value;
      saveColour("bar", barPicker.value);
    });
  }

  // Reset the active theme's colours to factory defaults.
  const resetBtn = document.getElementById("reset-theme-colours");
  if (resetBtn) {
    resetBtn.addEventListener("click", () => {
      const d = THEME_COLOUR_DEFAULTS[_activeTheme] || THEME_COLOUR_DEFAULTS.dark;
      _themeColours[_activeTheme] = { highlight: d.highlight, bar: d.bar };
      reflectTheme(_activeTheme);
      chrome.storage.local.set({ themeColours: _themeColours });
    });
  }

  // Reading-overlay text size (theme-independent).
  const ovSize = document.getElementById("ov-size");
  if (ovSize) {
    ovSize.addEventListener("input", () => {
      const v = parseInt(ovSize.value, 10);
      document.getElementById("ov-size-val").textContent = v + "px";
      chrome.storage.local.set({ overlayTextSize: v });
    });
  }
}


function stripMarkersForDisplay(text) {
  return text
    .replace(/\|\/?(H[1-3]|BOLD|ITALIC|CODE|CALLOUT|CAPTION|LIST)\|/g, '')
    .replace(/\|BREAK\|/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

document.addEventListener("DOMContentLoaded", () => {
  // Keep temperature in sync with the server (and thus the tuning dropdown) when
  // the popup gets focus back, which covers having both UIs open at once.
  window.addEventListener("focus", () => {
    kamFetch("http://127.0.0.1:5050/settings", {})
      .then(r => r.json())
      .then(s => {
        if (!s) return;
        const ts = document.getElementById("temp-slider");
        if (s.temperature != null && ts && parseFloat(ts.value) !== s.temperature) {
          ts.value = s.temperature;
          updateTemperature(s.temperature, true);
        }
        const sp = document.getElementById("speed-slider");
        if (s.speed != null && sp && parseFloat(sp.value) !== s.speed) {
          sp.value = s.speed;
          updateSpeed(s.speed, true);
        }
      }).catch(() => {});
  });
  initSettings();
  checkServer();
  checkIfPlaying();
  const ll = document.getElementById("learner-link");
  if (ll) ll.addEventListener("click", (e) => {
    e.preventDefault();
    const _pUrl = chrome.runtime.getURL("player.html");
  chrome.tabs.query({ url: _pUrl }, tabs => {
    if (tabs && tabs.length > 0) chrome.tabs.update(tabs[0].id, { active: true });
    else chrome.tabs.create({ url: _pUrl, active: true });
  });
  });
  document.getElementById("speak-btn").addEventListener("click", speak);
  document.getElementById("stop-btn").addEventListener("click", stopAudio);

  // The dashboard button, which opens the full Chunks, Report, Rules and AI UI.
  const dashBtn = document.getElementById("open-dashboard");
  if (dashBtn) dashBtn.addEventListener("click", () => { openDashboard(); window.close(); });

  // Page-highlight toggle. State lives in chrome.storage.local; content.js
  // reacts instantly via its storage listener. We just flip the value and
  // reflect it on the button label/style.
  const hlBtn = document.getElementById("toggle-highlight");
  if (hlBtn) {
    const paintHlBtn = (on) => {
      hlBtn.textContent = on ? "✏️ Page Highlight: On" : "✏️ Page Highlight: Off";
      hlBtn.classList.toggle("off", !on);
    };
    chrome.storage.local.get({ highlightEnabled: true }, c => paintHlBtn(c.highlightEnabled !== false));
    hlBtn.addEventListener("click", () => {
      chrome.storage.local.get({ highlightEnabled: true }, c => {
        const next = !(c.highlightEnabled !== false);
        chrome.storage.local.set({ highlightEnabled: next }, () => paintHlBtn(next));
      });
    });
  }

  // Header-bar toggle. Same storage-backed pattern: content.js shows/hides the
  // overlay bar instantly via its storage listener.
  const barBtn = document.getElementById("toggle-headerbar");
  if (barBtn) {
    const paintBarBtn = (on) => {
      barBtn.textContent = on ? "📋 Header Bar: On" : "📋 Header Bar: Off";
      barBtn.classList.toggle("off", !on);
    };
    chrome.storage.local.get({ overlayEnabled: true }, c => paintBarBtn(c.overlayEnabled !== false));
    barBtn.addEventListener("click", () => {
      chrome.storage.local.get({ overlayEnabled: true }, c => {
        const next = !(c.overlayEnabled !== false);
        chrome.storage.local.set({ overlayEnabled: next }, () => paintBarBtn(next));
      });
    });
  }

  // Feedback buttons (moved off inline onclick for MV3 CSP compliance).
  const fbUp   = document.getElementById("fb-up-btn");
  const fbDown = document.getElementById("fb-down-btn");
  if (fbUp)   fbUp.addEventListener("click", thumbsUp);
  if (fbDown) fbDown.addEventListener("click", thumbsDown);
  // The mode tabs are divs, so a click was the only way to use them. They are
  // focusable now (role and tabindex are in popup.html), and Enter or Space
  // picks the one in focus, as it would for a real tab.
  ["selection", "custom", "page"].forEach(m => {
    const tab = document.getElementById(`tab-${m}`);
    tab.addEventListener("click", () => setMode(m));
    tab.addEventListener("keydown", e => {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setMode(m); }
    });
  });
  initCustomDraft();
  initPrivateToggle();
  initResumeBar();
  document.getElementById("speed-slider").addEventListener("input", (e) => updateSpeed(e.target.value));
  document.getElementById("temp-slider").addEventListener("input", (e) => updateTemperature(e.target.value));
  document.getElementById("btn-pause").addEventListener("click", () => {
    chrome.runtime.sendMessage({ action: "pauseResume" }).catch(() => {});
  });
  // Temperature and speed: the server's live values are the single source of
  // truth (the tuning dropdown writes to them too). Read on open so popup and
  // dropdown always agree. Fall back to local storage if the server is down.
  kamFetch("http://127.0.0.1:5050/settings", {
  })
    .then(r => r.json())
    .then(s => {
      const ts = document.getElementById("temp-slider");
      if (s && s.temperature != null && ts) { ts.value = s.temperature; updateTemperature(s.temperature, true); }
      const sp = document.getElementById("speed-slider");
      if (s && s.speed != null && sp) {
        sp.value = s.speed;
        document.getElementById("speed-value").textContent = `${parseFloat(s.speed).toFixed(2)}x`;
        chrome.runtime.sendMessage({ action: "setSpeed", speed: s.speed }).catch(() => {});
      }
      chrome.storage.local.set({ temperature: s && s.temperature, speed: s && s.speed });
    })
    .catch(() => {
      chrome.storage.local.get(['temperature', 'speed'], (data) => {
        if (data.temperature) {
          const ts = document.getElementById("temp-slider");
          if (ts) { ts.value = data.temperature; updateTemperature(data.temperature, true); }
        }
        if (data.speed) {
          const sp = document.getElementById("speed-slider");
          if (sp) { sp.value = data.speed; document.getElementById("speed-value").textContent = `${parseFloat(data.speed).toFixed(2)}x`; }
        }
      });
    });
});

function checkIfPlaying() {
  chrome.runtime.sendMessage({ action: "getStatus" }, (response) => {
    void chrome.runtime.lastError;   // a worker that is not up yet is not an error here
    if (response && response.isPlaying) {
      allChunks         = response.chunks || [];
      currentChunkIndex = response.currentChunkIndex || 0;
      _chunkIds         = Object.assign({}, response.chunkIds || {});
      showPlayer(true);
      showPrivateLock(response.private === true);
      paintResume(null);
      updatePlayerLabel(currentChunkIndex + 1, allChunks.length);
      updateProgressFill(currentChunkIndex + 1, allChunks.length);
      renderTextView(allChunks, currentChunkIndex);
      document.getElementById("speak-btn").disabled = true;
      const paused = response.isPaused;
      document.getElementById("btn-pause").textContent    = paused ? "▶" : "⏸";
      document.getElementById("btn-pause").classList.toggle("paused", paused);
    } else {
      // A read the server failed is not playing either, and the worker keeps
      // the reason, so a popup opened afterwards can still say what happened.
      if (response && response.error && response.error.message) {
        _playbackErrorShown = true;
        showError(response.error.message);
      }
      // Nothing is playing, so a read that was left part-way can be offered back.
      checkResume();
    }
  });
}

chrome.runtime.onMessage.addListener((request) => {
  if (request.action === "chunkStatus") {
    currentChunkIndex = request.current - 1;
    updatePlayerLabel(request.current, request.total);
    updateActiveChunk(currentChunkIndex);
    updateProgressFill(request.current, request.total);
    // The read is moving again, so a line saying it had stopped is out of date.
    if (_playbackErrorShown) { _playbackErrorShown = false; hideError(); }
  }
  // The server stopped answering part-way through. The worker halts the read
  // and keeps its place, so the player and the chunk list stay as they are,
  // the reason is shown, and the Resume line is offered to carry on from the
  // same chunk. A silent stall used to look exactly like a read that finished.
  // Speak is freed as well, so starting something else is still possible.
  if (request.action === "playbackError") {
    _playbackErrorShown = true;
    showError(request.message || "The server stopped answering. Press Resume to carry on.");
    const speakBtn = document.getElementById("speak-btn");
    if (speakBtn) speakBtn.disabled = !_serverOnline;
    checkResume();
  }
  if (request.action === "playbackFinished") {
    showPlayer(false);
    document.getElementById("speak-btn").disabled = false;
    document.getElementById("text-view").style.display = "none";
    allChunks = [];
  }
  if (request.action === "pausedPlaying") {
    const btn = document.getElementById("btn-pause");
    if (btn) { btn.textContent = "▶"; btn.classList.add("paused"); }
  }
  if (request.action === "resumedPlaying") {
    const btn = document.getElementById("btn-pause");
    if (btn) { btn.textContent = "⏸"; btn.classList.remove("paused"); }
  }
  if (request.action === "chunkReady") {
    _lastChunkId   = request.chunkId   || null;
    _lastChunkText = request.chunkText || "";
    if (request.index != null && request.chunkId) _chunkIds[request.index] = request.chunkId;
    _showFeedbackButtons();
  }
});

// True while the error line is showing a playbackError from the worker.
let _playbackErrorShown = false;

// --- Resume where you left off ---
// The worker keeps the position of a read that was stopped part-way and gives
// it back through getResume. The line is built here so it can be tested: the
// position goes first, because the title is what gets cut off when the two do
// not fit. A worker that does not know the action answers with nothing, and
// then there is nothing to show.
function resumeLine(resume) {
  if (!resume || !(resume.total > 0)) return "";
  const at    = Math.min(Math.max((parseInt(resume.index, 10) || 0) + 1, 1), resume.total);
  const title = String(resume.title || "").replace(/\s+/g, " ").trim();
  return `Left off at ${at} of ${resume.total}` + (title ? ` · ${title}` : "");
}

function paintResume(resume) {
  const bar  = document.getElementById("resume-bar");
  const text = document.getElementById("resume-text");
  if (!bar || !text) return;
  const line = resumeLine(resume);
  bar.style.display = line ? "flex" : "none";
  text.textContent  = line;
  text.title        = line ? [resume.title, resume.url].filter(Boolean).join("\n") : "";
}

function checkResume() {
  try {
    chrome.runtime.sendMessage({ action: "getResume" }, (response) => {
      if (chrome.runtime.lastError) { paintResume(null); return; }
      paintResume(response && response.resume);
    });
  } catch (e) { /* no worker to ask, so no line */ }
}

function initResumeBar() {
  const go   = document.getElementById("resume-btn");
  const drop = document.getElementById("resume-dismiss");
  if (go) go.addEventListener("click", () => {
    paintResume(null);
    hideError();
    _playbackErrorShown = false;
    // The worker is told the speed on the slider and the tab in front, which
    // it uses when the page the read came from is no longer open.
    const slider = document.getElementById("speed-slider");
    const speed  = slider ? parseFloat(slider.value) : undefined;
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      void chrome.runtime.lastError;
      const tabId = tabs && tabs[0] ? tabs[0].id : undefined;
      chrome.runtime.sendMessage({ action: "resumeRead", speed, tabId }, () => {
        void chrome.runtime.lastError;
        // The worker starts the read itself, so the player is filled in from
        // its status. Asked twice, since the first answer can come before the
        // read has begun.
        checkIfPlaying();
        setTimeout(checkIfPlaying, 800);
      });
    });
  });
  if (drop) drop.addEventListener("click", () => {
    paintResume(null);
    chrome.runtime.sendMessage({ action: "forgetResume" }, () => { void chrome.runtime.lastError; });
  });
}

// --- Private reads ---
// A private read is one whose text the server does not keep in the chunk
// history. The toggle is remembered, and a read from an incognito tab is
// private whatever the toggle says.
function initPrivateToggle() {
  const box = document.getElementById("private-read");
  if (!box) return;
  chrome.storage.local.get({ kamPrivateRead: false }, c => {
    box.checked = !!(c && c.kamPrivateRead);
  });
  box.addEventListener("change", () => {
    chrome.storage.local.set({ kamPrivateRead: box.checked });
  });
}

function showPrivateLock(on) {
  const lock = document.getElementById("private-lock");
  if (lock) lock.style.display = on ? "inline" : "none";
}

// --- Waking a sleeping model ---
// The server drops the voice model after a while idle, and the first chunk
// then waits for it to load. Opening the popup is a fair sign that a read is
// coming, so I ask for the wake now. It is tried once per popup, it never
// holds the UI up, and a failure is not worth a message, since the read wakes
// the model anyway.
let _prewakeTried = false;
function prewakeModel() {
  if (_prewakeTried) return;
  _prewakeTried = true;
  kamFetch(`${SERVER}/standby`, {})
    .then(r => (r.ok ? r.json() : null))
    .then(s => {
      if (!s || s.state !== "standby") return null;
      return kamFetch(`${SERVER}/standby`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ wake: true })
      });
    })
    .catch(() => {});
}

// --- Quality feedback ---
let _lastChunkId   = null;
let _lastChunkText = "";
let _feedbackOpen  = false;
// The server's id for each chunk of the current read, by index, as the worker
// announces them. A report has to carry the id, because the server can only
// re-derive one by hashing the text it is given, and the text shown here is
// the display text rather than the spoken text the id was made from, so the
// two never match and the report reaches no chunk.
let _chunkIds      = {};

// The dashboard hand-off. The text goes first, as it always did, and the id
// follows when one is known. encodeURIComponent turns any & in the text into
// %26, so the id separator cannot be confused with the text.
function reportHash(text, chunkId) {
  return "#report:" + encodeURIComponent(text || "") +
         (chunkId ? "&id=" + encodeURIComponent(chunkId) : "");
}

function _showFeedbackButtons() {
  const bar = document.getElementById("feedback-bar");
  if (bar) bar.style.display = "flex";
}
function _hideFeedbackButtons() {
  const bar = document.getElementById("feedback-bar");
  if (bar) bar.style.display = "none";
  _feedbackOpen = false;
}

function thumbsUp() {
  kamFetch("http://127.0.0.1:5050/report", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ chunk_id: _lastChunkId, chunk_text: _lastChunkText, issue: "OTHER", action: "IGNORE", confidence: "HIGH", notes: "user_approved" })
  }).catch(() => {});
  _hideFeedbackButtons();
}

function thumbsDown() {
  const url = chrome.runtime.getURL("player.html") + reportHash(_lastChunkText, _lastChunkId);
  chrome.tabs.query({ url: chrome.runtime.getURL("player.html") }, tabs => {
    if (tabs && tabs.length > 0) chrome.tabs.update(tabs[0].id, { url, active: true });
    else chrome.tabs.create({ url, active: true });
  });
  _hideFeedbackButtons();
}

function openDashboard() {
  const url = chrome.runtime.getURL("player.html");
  chrome.tabs.query({ url }, tabs => {
    if (tabs && tabs.length > 0) chrome.tabs.update(tabs[0].id, { active: true });
    else chrome.tabs.create({ url, active: true });
  });
}

let _checkTimer = null;
async function checkServer() {
  clearTimeout(_checkTimer);
  // The fetch verdict is computed FIRST and every DOM update is null-safe.
  // A previous version updated elements inside the try block, so a missing
  // or renamed element, which happened after theme edits to popup.html, threw
  // after a successful health check and quietly painted "Server offline".
  let online = false;
  try {
    // 3-second timeout so we never hang on "Checking server..."
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 3000);
    const res  = await fetch(`${SERVER}/health`, { signal: controller.signal });
    clearTimeout(timer);
    online = res.ok;
    if (!res.ok) console.warn("[KAM] health check: server answered", res.status);
  } catch (err) {
    // A server that simply isn't running yet throws "Failed to fetch" or an
    // AbortError on timeout. That is the expected pre-start state, polled every
    // 3s, so I don't log it as an error since that just spams the console. Any
    // other unexpected error still gets surfaced.
    const expected = err && (err.name === "AbortError" ||
                             /Failed to fetch|NetworkError/i.test(String(err.message || err)));
    if (!expected) console.error("[KAM] health check failed:", err);
  }
  _serverOnline = online;
  paintStatus();
  if (online) prewakeModel();
  // Every 3 seconds while the popup is open, online or not. Polling only while
  // offline meant a server stopped with the popup open went on reading
  // "online", and there was nothing to offer a stop from. One timer at a time,
  // since a ready event also calls this and each call would otherwise add one.
  clearTimeout(_checkTimer);
  _checkTimer = setTimeout(checkServer, 3000);
}

// =============================================================================
// SERVER STATUS AND THE START BUTTON
// =============================================================================
//
// The server writes its progress to .kam_stage as it boots and the native host
// relays each change, so the popup can say which part of a slow start it is on
// rather than sitting on "offline" for most of a minute. Loading torch and XTTS
// is the long one and it is worth naming, because a progress line that stops
// moving there looks broken and is not.
//
// The names below are the server's own stage strings. An unrecognised one is
// shown as-is rather than swallowed, since a stage nothing renders is how you
// end up with a blank line and no idea why.
const BOOT_STEPS = [
  ["process-started",    "Starting up"],
  ["flask-import",       "Loading the web layer"],
  ["torch-tts-imported", "Loading PyTorch and XTTS"],
  ["device-probe",       "Choosing the compute device"],
  ["model-loading",      "Loading the voice model"],
  ["adapting",           "Adapting to your hardware"],
  ["benchmarking",       "Measuring synthesis speed"],
  ["model-loaded",       "Model ready"],
];
const BOOT_ASIDES = {
  "standby":           "Standing by to save power",
  "waking":            "Waking the model",
  "no-voice-clips":    "No voice clips found — record some first",
  "duplicate-aborted": "Another server is already running",
  "ready":             "Ready",
};

let _serverOnline = false;
let _hostState    = { connected: false, running: false, ready: false, stage: "", error: "", startedAt: 0 };
// What this popup asked for, and when. The worker's state is what the host
// reported; these cover the gaps either side of it: the moment before the first
// stage arrives, and a stop, which nothing narrates when the server was not the
// host's own. `note` is a short-lived line for a stop that failed.
let _asked = { startAt: 0, stopAt: 0, note: "", noteAt: 0 };

// A boot that has not answered within five minutes is not booting any more, it
// is a stage left behind by a server that died without saying so. Five, not
// one, because a first boot measures synthesis speed and can take a while.
const START_GRACE_MS = 300000, STOP_GRACE_MS = 30000, NOTE_MS = 8000;

function _stepFor(stage) {
  const i = BOOT_STEPS.findIndex(s => s[0] === stage);
  if (i >= 0) return { label: BOOT_STEPS[i][1], pct: Math.round((i + 1) / BOOT_STEPS.length * 100) };
  if (BOOT_ASIDES[stage]) return { label: BOOT_ASIDES[stage], pct: null };
  return stage ? { label: stage, pct: null } : null;
}

// Everything the status bar shows, worked out from what is known. Kept pure so
// it can be tested without a popup; paintStatus only copies it onto elements.
function statusView(online, host, asked, now) {
  host = host || {}; asked = asked || {};
  const note = asked.note && now - asked.noteAt < NOTE_MS ? asked.note : "";

  if (online) {
    if (asked.stopAt && now - asked.stopAt < STOP_GRACE_MS) {
      return { dot: "busy", text: "Stopping the server…", step: "", pct: null,
               button: "stop", disabled: true, title: "Stopping…" };
    }
    return { dot: "online", text: "Server online", step: note, pct: null,
             button: "stop", disabled: false, title: "Stop the KAM TTS server" };
  }

  // Booting: this popup just asked, or the host is connected and started a boot
  // recently. The click counts on its own so "Starting up" shows at once rather
  // than after the first stage, which is what made the progress look absent.
  const clicked  = asked.startAt && now - asked.startAt < START_GRACE_MS;
  const hostBoot = host.connected && host.stage && host.startedAt
                   && now - host.startedAt < START_GRACE_MS;
  if (!host.error && (clicked || hostBoot)) {
    // Ready but not yet answering is the model warming up, the last few seconds.
    const info = host.ready || host.stage === "ready"
      ? { label: "Warming up the voice model", pct: 100 }
      : _stepFor(host.stage || "process-started");
    return { dot: "busy", text: "Starting the server…", step: info ? info.label : "",
             pct: info ? info.pct : null, button: "start", disabled: true, title: "Starting…" };
  }

  return { dot: "offline", text: host.error || "Server offline",
           step: note && note !== host.error ? note : "", pct: null,
           button: "start", disabled: false, title: "Start the KAM TTS server" };
}

function paintStatus() {
  const dot  = document.getElementById("status-dot");
  const txt  = document.getElementById("status-text");
  const step = document.getElementById("status-step");
  const prog = document.getElementById("status-prog");
  const btn  = document.getElementById("status-start");
  const speak= document.getElementById("speak-btn");
  if (!dot || !txt) return;

  const v = statusView(_serverOnline, _hostState, _asked, Date.now());
  // A request is finished once the health check agrees with it.
  if (_serverOnline) _asked.startAt = 0;
  else _asked.stopAt = 0;

  dot.className = "status-dot" + (v.dot === "online" ? " online" : v.dot === "offline" ? " offline" : "");
  // Both lines are aria-live, and this runs every three seconds, so the text
  // is only written when it has changed. Writing the same words again would
  // have a screen reader announce "Server online" over and over.
  if (txt.textContent !== v.text) txt.textContent = v.text;
  if (step) {
    step.style.display = v.step ? "block" : "none";
    if (step.textContent !== v.step) step.textContent = v.step;
  }
  if (prog) {
    const show = v.pct !== null && v.pct !== undefined;
    prog.style.display = show ? "block" : "none";
    if (show) prog.firstElementChild.style.width = v.pct + "%";
  }
  if (btn) {
    btn.classList.add("show");
    btn.classList.toggle("stop", v.button === "stop");
    btn.textContent = v.button === "stop" ? "■" : "⏻";
    btn.disabled = v.disabled;
    btn.title = v.title;
    btn.setAttribute("aria-label", v.title);   // the button is a bare symbol
  }
  if (speak) speak.disabled = !_serverOnline;
}

// The worker owns the host connection, so the popup asks it for the current
// state on open and then listens. Without the initial ask, reopening the popup
// mid-boot would show "offline" until the next stage happened to change.
try {
  chrome.runtime.sendMessage({ action: "hostState" }, s => {
    if (chrome.runtime.lastError) return;
    if (s) { _hostState = s; paintStatus(); }
  });
  chrome.runtime.onMessage.addListener(msg => {
    if (msg && msg.action === "hostEvent" && msg.state) {
      _hostState = msg.state;
      const ev = msg.event;
      if (ev && ev.type === "error") {
        // A failed start or stop ends the wait for it and says why.
        _asked.startAt = 0; _asked.stopAt = 0;
        _asked.note = ev.message || ""; _asked.noteAt = Date.now();
      }
      paintStatus();
      // Confirm with a real health check rather than waiting for the next poll.
      if (_hostState.ready || (ev && (ev.type === "exit" || ev.type === "stopping"))) checkServer();
    }
  });
} catch (e) { /* worker not up yet; the health check still drives the dot */ }

document.addEventListener("DOMContentLoaded", () => {
  const btn = document.getElementById("status-start");
  if (!btn) return;
  btn.addEventListener("click", () => {
    if (_serverOnline) {
      _asked.stopAt = Date.now(); _asked.note = "";
      paintStatus();
      chrome.runtime.sendMessage({ action: "hostStop" }, () => {
        if (chrome.runtime.lastError) {
          _asked.stopAt = 0;
          _asked.note = "Could not reach the extension worker. Reload the extension.";
          _asked.noteAt = Date.now();
        }
        paintStatus();
      });
      return;
    }
    _asked.startAt = Date.now(); _asked.note = "";
    _hostState = Object.assign({}, _hostState, { error: "", ready: false, stage: "" });
    paintStatus();
    chrome.runtime.sendMessage({ action: "hostStart" }, s => {
      if (chrome.runtime.lastError) {
        _asked.startAt = 0;
        _hostState.error = "Could not reach the extension worker. Reload the extension.";
      } else if (s) {
        _hostState = s;
      }
      paintStatus();
    });
  });
});

function setMode(mode) {
  currentMode = mode;
  ["selection", "custom", "page"].forEach(m => {
    const tab = document.getElementById(`tab-${m}`);
    tab.classList.toggle("active", m === mode);
    tab.setAttribute("aria-selected", m === mode ? "true" : "false");
  });
  document.getElementById("custom-text-area").style.display = mode === "custom" ? "block" : "none";
  if (mode === "custom") loadScannedText();
}

// --- The Custom Text box keeps what is in it ---
// The popup is destroyed the moment it loses focus, and the box went with it,
// so switching tabs to copy one more paragraph lost everything typed so far.
// The draft is kept in session storage, which lasts as long as the browser
// is open and is never written to disk, and is put back when the popup opens.
const DRAFT_KEY      = "kamCustomDraft";
const SCAN_TAKEN_KEY = "kamScanTaken";
// The scanned text this box was filled from, if it was, so I know which one
// to clear out of storage once it has been dealt with.
let _scanTaken = "";

function _sessionStore() {
  try { return (chrome.storage && chrome.storage.session) || null; }
  catch (e) { return null; }
}
const _quiet = () => { void chrome.runtime.lastError; };

function saveCustomDraft(value) {
  const store = _sessionStore();
  if (!store) return;
  try {
    if (value) store.set({ [DRAFT_KEY]: value }, _quiet);
    else       store.remove(DRAFT_KEY, _quiet);
  } catch (e) { /* over quota or unavailable, so the draft is just not kept */ }
}

function initCustomDraft() {
  const box = document.getElementById("custom-input");
  if (!box) return;
  const store = _sessionStore();
  if (store) {
    try {
      store.get([DRAFT_KEY, SCAN_TAKEN_KEY], d => {
        if (chrome.runtime.lastError || !d) return;
        // Only into an empty box, in case something was typed before this came back.
        if (d[DRAFT_KEY] && !box.value) box.value = d[DRAFT_KEY];
        _scanTaken = d[SCAN_TAKEN_KEY] || "";
      });
    } catch (e) { /* no session storage, so there is no draft to restore */ }
  }
  box.addEventListener("input", () => {
    saveCustomDraft(box.value);
    // Emptying the box is the user saying they are done with what was in it.
    if (!box.value.trim()) releaseScannedText();
  });
}

// Text read off a photo in the dashboard's Scan panel is handed over through
// storage rather than spoken from there, so it arrives here to be read over and
// edited before it is played, the same as anything typed in.
//
// It only fills an empty box, since quietly overwriting something half-typed
// would be worse than making you press the tab again. It used to be removed
// from storage the moment it was loaded, so closing the popup before pressing
// Speak lost the scan for good. It stays now until it has been spoken or the
// box has been cleared, which is releaseScannedText below.
function loadScannedText() {
  const box = document.getElementById("custom-input");
  if (!box || box.value.trim()) return;
  try {
    chrome.storage.local.get("kamScanText", d => {
      if (chrome.runtime.lastError) return;
      const text = d && d.kamScanText;
      if (!text || box.value.trim()) return;
      box.value  = text;
      _scanTaken = text;
      saveCustomDraft(text);
      const store = _sessionStore();
      if (store) { try { store.set({ [SCAN_TAKEN_KEY]: text }, _quiet); } catch (e) {} }
      const info = document.getElementById("status-step");
      if (info) { info.style.display = "block"; info.textContent = "Scanned text loaded"; }
    });
  } catch (e) { /* storage unavailable — the box just stays empty */ }
}

// The scan has been spoken, or the box it was in has been cleared, so it can
// leave storage. Only the scan this box took is removed: a newer one that
// arrived since is left for the next visit.
function releaseScannedText() {
  if (!_scanTaken) return;
  const taken = _scanTaken;
  _scanTaken = "";
  const store = _sessionStore();
  if (store) { try { store.remove(SCAN_TAKEN_KEY, _quiet); } catch (e) {} }
  try {
    chrome.storage.local.get("kamScanText", d => {
      if (chrome.runtime.lastError) return;
      if (d && d.kamScanText === taken) chrome.storage.local.remove("kamScanText");
    });
  } catch (e) { /* storage unavailable, so there is nothing to clear */ }
}

function updateSpeed(val, skipPost) {
  const speed = parseFloat(val);
  document.getElementById("speed-value").textContent = `${speed.toFixed(2)}x`;
  chrome.runtime.sendMessage({ action: "setSpeed", speed }).catch(() => {});
  // Mirror to the server so the tuning dropdown's Speed slider stays in sync
  // (skipPost avoids echoing a value we just read from the server).
  if (!skipPost) {
    kamFetch("http://127.0.0.1:5050/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ speed })
    }).catch(() => {});
    chrome.storage.local.set({ speed });
  }
}

function updateTemperature(val, skipPost) {
  const temp = parseFloat(val);
  document.getElementById("temp-value").textContent = temp.toFixed(2);

  // Gradient track: blue (cold 0.05) → red (hot 0.90)
  const pct = ((temp - 0.05) / (0.90 - 0.05)) * 100;
  // Interpolate hue: 220 (blue) → 0 (red)
  const hue  = Math.round(220 - (220 * pct / 100));
  const fill = `hsl(${hue},90%,55%)`;
  const slider = document.getElementById("temp-slider");
  if (slider) {
    slider.style.accentColor = fill;
    slider.style.setProperty("--fill", fill);
    slider.style.background =
      `linear-gradient(to right, ${fill} ${pct}%, #2a2a2a ${pct}%)`;
  }

  // Send to server live (unless we're just reflecting a value we read FROM the
  // server, which would be a redundant echo).
  if (!skipPost) {
    kamFetch("http://127.0.0.1:5050/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ temperature: temp })
    }).catch(() => {});
    chrome.storage.local.set({ temperature: temp });
  }
}

function stopAudio() {
  // The worker keeps the place of a read stopped part-way, so once it has
  // stopped I ask whether there is one to offer back.
  chrome.runtime.sendMessage({ action: "stop" }, () => {
    void chrome.runtime.lastError;
    checkResume();
  });
  showPlayer(false);
  document.getElementById("speak-btn").disabled = false;
  document.getElementById("text-view").style.display = "none";
  allChunks = [];
}


async function speak() {
  hideError();
  let text = "";

  // Stage feedback: the first action after a cold start does real work (waking
  // the service worker, fetching the token, waking the model from standby).
  // Without visible progress that delay reads as a broken model.
  showInfo("⏳ Preparing…");
  if (currentMode === "custom") {
    const typed = document.getElementById("custom-input").value;
    if (!typed.trim()) { showError("Please type some text first."); return; }
    // Line breaks become |BREAK| here. The chunker collapses all whitespace, so
    // without this a heading ran into its paragraph and verse into one line.
    text = customTextToMarked(typed);
  } else if (currentMode === "page") {
    showInfo("⏳ Reading the page…");
    text = await _withExtractionTimeout(getPageText());
    const problem = extractionProblem(text);
    if (problem) { showError(problem); return; }
    if (!text) { showError("Could not extract text from page."); return; }
  } else {
    showInfo("⏳ Reading your selection…");
    text = await _withExtractionTimeout(getSelectedText());
    const problem = extractionProblem(text);
    if (problem) { showError(problem); return; }
    if (!text) { showError("No text selected. Highlight text on the page first."); return; }
  }

  // The voice is English, and everything outside ASCII is stripped before it
  // is spoken. Text in another script would come out as nothing at all, and
  // the read would start, show its chunks and play silence, so I stop here
  // and say why. The markers go first, since their letters are Latin.
  if (typeof kamMostlyNonLatin === "function" &&
      kamMostlyNonLatin(text.replace(/\|\/?[A-Z0-9]+\|/g, " "))) {
    showError("KAM TTS reads English only for now. This text looks like another language.");
    return;
  }

  showInfo("⏳ Splitting into chunks…");
  allChunks = splitIntoChunks(text);
  allChunks = await applyBoundaryCorrections(allChunks);

  // The count is what the reader needs. The rest is diagnosis, so it lives in
  // the line's tooltip, where it is still there for whoever is looking for it.
  const _breaks = (text.match(/\|BREAK\|/g) || []).length;
  const _detail = text.length + " characters · " + _breaks + " breaks";
  if (allChunks.length === 0) {
    showError("Nothing readable was found in that text.", _detail);
    return;
  }
  // Debug logging for chunk diagnosis used to live here and has been removed
  const _orphans = allChunks.filter(c => /^(and|but|or|so|yet|nor|for)\b/i.test(c) && c.length <= 50);
  showInfo(allChunks.length + " chunk" + (allChunks.length === 1 ? "" : "s"),
    _detail + (_orphans.length > 0 ? " · " + _orphans.length + " orphan(s)" : " · clean"));

  currentChunkIndex = 0;
  _chunkIds = {};   // a new read, so the old read's ids name other chunks now
  const speed = parseFloat(document.getElementById("speed-slider").value);

  showPlayer(true);
  updatePlayerLabel(1, allChunks.length);
  updateProgressFill(1, allChunks.length);
  renderTextView(allChunks, 0);
  document.getElementById("speak-btn").disabled = true;

  chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
    if (!tabs || !tabs[0]) {
      showError("No active tab found — cannot start playback."); return;
    }
    const tab   = tabs[0];
    const tabId = tab.id;
    // Unique nonce prevents background.js processing the same session twice
    // even if Chrome delivers the message more than once during SW wake-up.
    const nonce = Date.now() + '-' + Math.random().toString(36).slice(2);
    // Solid digestion (learning from heard-but-unrated chunks) applies only to
    // real reading content, so Read Page and Selected Text. Custom Text is
    // one-off typed input and shouldn't shape the per-sentence-type learning.
    const digestible = (currentMode === "page" || currentMode === "selection");
    const fromPage   = currentMode !== "custom";
    // The title and address let the worker label the read it saves for
    // "resume where you left off". Typed text did not come from the tab, so it
    // is not labelled with whatever page happens to be open behind the popup.
    const message = {
      action: "startSpeaking", chunks: allChunks, startIndex: 0, speed, tabId, nonce, digestible,
      title: fromPage ? (tab.title || "") : "Custom text",
      url:   fromPage ? (tab.url   || "") : "",
    };
    // Private when the toggle is on, and always from an incognito window,
    // since nobody browsing privately expects the text kept in a history.
    const privateBox = document.getElementById("private-read");
    const isPrivate  = !!(privateBox && privateBox.checked) || !!tab.incognito;
    if (isPrivate) message.private = true;
    showPrivateLock(isPrivate);
    paintResume(null);   // a new read replaces whatever was on offer
    const wasCustom = !fromPage;
    chrome.runtime.sendMessage(message, (response) => {
      if (chrome.runtime.lastError || !response) {
        showError("Background worker unreachable — reload the extension.");
        showPlayer(false);
        document.getElementById("speak-btn").disabled = false;
        return;
      }
      // The scanned page has now been spoken, so it can leave storage.
      if (wasCustom) releaseScannedText();
    });
  });
}

// =============================================================================
// READING
// =============================================================================
// The chunker and the page and selection extractors are in reader-core.js,
// which popup.html loads before this file. They moved there so the worker
// can run them too, for the right-click menu.

// =============================================================================
// UI HELPERS
// =============================================================================

function renderTextView(chunks, activeIndex) {
  const view = document.getElementById("text-view");
  view.style.display = "block";
  view.innerHTML     = "";
  chunks.forEach((chunk, i) => {
    const div = document.createElement("div");
    div.className = "chunk-item" +
      (i === activeIndex ? " active" : i < activeIndex ? " played" : "");
    div.style.position = "relative";
    div.style.paddingRight = "20px";
    const text = stripMarkersForDisplay(chunk);
    div.textContent = text;
    const jump = () => {
      chrome.runtime.sendMessage({ action: "jumpTo", index: i }).catch(() => {});
    };
    div.addEventListener("click", jump);
    // A row is a div that jumps the read to its chunk, so it could only be
    // used with a mouse. It takes focus now and answers Enter and Space. The
    // target check keeps a key pressed on the flag inside it from jumping too.
    div.setAttribute("role", "button");
    div.setAttribute("tabindex", "0");
    div.addEventListener("keydown", (e) => {
      if (e.target !== div) return;
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); jump(); }
    });

    // The flag button, appended to chunk-item so the class styles still apply
    const flagBtn = document.createElement("button");
    flagBtn.textContent = "⚑";
    flagBtn.title = "Report this chunk";
    flagBtn.setAttribute("aria-label", "Report this chunk");
    flagBtn.style.cssText = "position:absolute;top:4px;right:6px;background:transparent;border:none;color:#555;cursor:pointer;font-size:10px;padding:0;line-height:1;transition:color 0.15s;z-index:1";
    flagBtn.addEventListener("mouseenter", () => flagBtn.style.color = "#ef4444");
    flagBtn.addEventListener("mouseleave", () => flagBtn.style.color = "#555");
    flagBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const base    = chrome.runtime.getURL("player.html");
      const hash    = reportHash(text, _chunkIds[i]);
      // Match player.html regardless of its current hash
      chrome.tabs.query({}, tabs => {
        const existing = tabs.find(t => t.url && t.url.startsWith(base));
        if (existing) {
          // The tab is already open, so I inject the hash through a script and
          // hashchange fires without a full page reload
          chrome.scripting.executeScript({
            target: { tabId: existing.id },
            func: (reportHash) => { window.location.hash = reportHash; },
            args: [hash]
          }).then(() => {
            chrome.tabs.update(existing.id, { active: true });
          }).catch(() => {
            // scripting isn't available, so fall back to updating the URL
            chrome.tabs.update(existing.id, { url: base + hash, active: true });
          });
        } else {
          chrome.tabs.create({ url: base + hash, active: true });
        }
      });
    });
    div.appendChild(flagBtn);
    view.appendChild(div);
  });
  scrollToActive(activeIndex);
}

function updateActiveChunk(index) {
  const view  = document.getElementById("text-view");
  if (!view) return;
  const items = view.querySelectorAll(".chunk-item");
  items.forEach((item, i) => {
    item.classList.remove("active", "played");
    if      (i === index) item.classList.add("active");
    else if (i < index)   item.classList.add("played");
  });
  scrollToActive(index);
}

function scrollToActive(index) {
  const view  = document.getElementById("text-view");
  const items = view.querySelectorAll(".chunk-item");
  if (items[index]) items[index].scrollIntoView({ block: "nearest", behavior: "smooth" });
}

function showPlayer(show) {
  document.getElementById("player-bar").style.display = show ? "block" : "none";
}

function updatePlayerLabel(current, total) {
  document.getElementById("player-label").textContent = `Reading ${current} of ${total}`;
}

function updateProgressFill(current, total) {
  const pct = total > 0 ? (current / total) * 100 : 0;
  document.getElementById("progress-fill").style.width = pct + "%";
}

// Both lines take an optional detail, which goes in the tooltip. The line
// itself says the one thing worth reading, and it is announced, since the
// element is aria-live.
function showError(msg, detail) {
  const el = document.getElementById("error-msg");
  el.textContent   = "⚠ " + msg;
  el.title         = detail || "";
  el.style.background = "#1a0a0a";
  el.style.borderColor = "#3a1a1a";
  el.style.color   = "#f87171";
  el.style.display = "block";
}

function showInfo(msg, detail) {
  const el = document.getElementById("error-msg");
  el.textContent   = "ℹ " + msg;
  el.title         = detail || "";
  el.style.background = "#0a1a1a";
  el.style.borderColor = "#1a3a3a";
  el.style.color   = "#67e8f9";
  el.style.display = "block";
}

function hideError() {
  document.getElementById("error-msg").style.display = "none";
}
